  "interviews": [
    {
      "categoryId": "P05-C2",
      "itemId": "P05-C2-I1",
      "interviewBlueprint": {
        "questionIntent": "분석 결과를 캠페인의 실행 대상으로 구체화하는 판단을 확인한다. 마지막 발주 품목과 시기에서 어떤 신호를 읽어 재접촉 대상을 우선했는지에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "오름퍼니처에서 6개월 이상 발주 없는 거래처를 대상으로 재접촉 캠페인을 진행했다.",
          "task": "마지막 발주 품목과 시기를 엑셀로 정리하고 의자·파티션 교체 주기가 돌아온 곳부터 연락 순서를 정했다.",
          "action": "먼저 연락할 거래처를 고를 때 결정적으로 본 신호와 그 신호가 드러난 발주 정보를 설명한다.",
          "result": "해당 신호가 재접촉 대상의 우선순위에 어떻게 반영됐는지 설명한다."
        },
        "expectedEvidence": [
          "먼저 연락할 거래처를 정할 때 본 구체적인 신호",
          "그 신호를 보여준 마지막 발주 품목과 시기 정보",
          "신호와 우선 연락 대상 사이의 연결"
        ]
      },
      "question": "오름퍼니처에서 휴면 거래처 재접촉 순서를 정하셨을 때, 마지막 발주 품목과 시기에서 어떤 신호를 보고 먼저 연락할 거래처를 고르셨나요?",
      "answerTip": "본인이 한 선택을 중심으로 짧게 말해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "우선 연락 대상을 가르는 신호를 발주 품목과 시기의 구체적인 특징으로 제시한다.",
            "제시한 신호가 재주문 가능성이 있는 거래처를 먼저 고르는 판단과 직접 연결된다."
          ]
        },
        "acceptable": {
          "criteria": [
            "교체 시점이나 발주 간격 등 우선 연락 대상을 고를 신호를 제시하지만 설명이 포괄적이다.",
            "발주 정보와 대상 선택의 연결은 드러나지만 어떤 거래처를 먼저 고르는지 구분이 충분히 구체적이지 않다."
          ]
        },
        "poor": {
          "criteria": [
            "먼저 연락할 거래처를 정할 때 본 신호를 제시하지 않고 연락 활동이나 재주문 성과만 말한다.",
            "제시한 신호가 발주 정보와 무관하거나 거래처의 연락 우선순위를 가르는 판단으로 이어지지 않는다."
