        "expectedSTAR": {
          "situation": "동네 꽃집 인스타그램 광고 소액 집행 분석에서 월 10만 원씩 광고를 집행했다.",
          "task": "게시물 유형인 사진형·가격 표기형·후기형의 클릭과 문의 DM 수를 엑셀로 비교했다.",
          "action": "캠페인 성과 판단에 가장 비중을 둔 지표를 구체적으로 밝힌다.",
          "result": "선택한 지표가 광고의 어떤 반응을 성과로 읽는 선택이었는지 설명한다."
        },
        "expectedEvidence": [
          "성과를 판단할 때 가장 비중을 둔 지표",
          "선택한 지표가 나타내는 광고 반응의 의미"
        ]
      },
      "question": "동네 꽃집 인스타그램 광고 소액 집행 분석에서 게시물 유형별 반응을 비교하셨을 때, 캠페인 성과를 판단하는 데 가장 비중을 둔 지표는 무엇이었나요?",
      "answerTip": "답을 먼저 말하고 짧게 풀어 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "문의 DM 수나 클릭 수 등 가장 비중을 둔 지표 하나를 명확하게 특정한다.",
            "선택한 지표를 광고가 이끌어 낸 고객 반응과 연결해 성과 판단에 맞는 구체적인 답을 한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "가장 비중을 둔 지표를 식별할 수 있지만 지표를 지칭하는 표현이 다소 포괄적이다.",
            "선택한 지표가 캠페인 성과와 관련은 있으나 어떤 고객 반응을 나타내는지 연결이 일반적이다."
          ]
        },
        "poor": {
          "criteria": [
            "여러 수치를 나열하거나 소재 변경 결과만 말해 가장 비중을 둔 지표를 식별할 수 없다.",
            "성과 지표 대신 소재에 대한 취향이나 도구 사용법을 말해 캠페인 성과 판단에서 벗어난다."
          ]
        }
      }
    }
  ]
}

